def unknown(code,meaning,sv=False):
 action=("Anteckna hela koden inklusive skiljetecken och suffix, leta upp E‑Nr och följ endast den exakta modellmanualen" if sv else "Record the complete code including punctuation and suffix, find the E-Nr, and follow only the exact model manual")
 v=build_sv(code,meaning,action) if sv else build_en(code,meaning,action)
 if sv:
  v['intro_html']=f"<p>För {code} krävs hela displaykoden och maskinens E‑Nr för en säker tolkning. {meaning.capitalize()}.</p><p>Använd inte kodbetydelser från en diskmaskin eller annan Bosch-serie. Ta inte bort paneler och beställ inte en reservdel innan rätt manual eller Bosch service har identifierat felet.</p>"
  v['causes_json']=[{"cause":"Ofullständig kodinformation","detail":"Skiljetecken, ytterligare siffror eller ett F kan ändra betydelsen. Dokumentera hela displayen."},{"cause":"Skillnader mellan modeller och marknader","detail":"Bosch-serier kan använda olika kodformat. E‑Nr behövs för rätt manual."},{"cause":"Ett tillstånd som manualen kan beskriva","detail":"Utför bara den yttre kontroll eller det användarunderhåll som uttryckligen anges för exakt modell."},{"cause":"Ett kvarstående servicebehov","detail":"Om rätt manual saknar användaråtgärd eller koden återkommer ska Bosch service diagnostisera maskinen."}]
 else:
  v['intro_html']=f"<p>{code} requires the complete display and the washer's E-Nr for safe interpretation. {meaning.capitalize()}.</p><p>Do not borrow a meaning from a dishwasher or another Bosch washer family. Do not remove panels or order a part until the exact manual or Bosch service identifies the fault.</p>"
  v['causes_json']=[{"cause":"Incomplete code information","detail":"Punctuation, extra digits or an F can change the meaning. Record the complete display."},{"cause":"Model and market differences","detail":"Bosch families can use different code formats. The E-Nr is needed for the correct manual."},{"cause":"A condition described by the exact manual","detail":"Perform only the external check or user maintenance explicitly stated for that model."},{"cause":"A persistent condition requiring service","detail":"If the exact manual provides no user action or the code returns, Bosch service should diagnose the washer."}]
 return v

def imbalance(sv=False):
 if sv:
  v=build_sv('E32','en obalanserad last har upptäckts','Pausa programmet, vänta tills trumman stannat och fördela tvätten jämnt')
  v.update({"title_tag":"Bosch tvättmaskin felkod E32: balansera tvätten","meta_description":"Visar Bosch-tvättmaskinen E32 eller F32? Så fördelar du tvätten säkert, kontrollerar lasten och ser när återkommande obalans kräver service.","description":"Bosch anger att E32/F32 betyder att maskinen har upptäckt en obalanserad last och kan minska eller stoppa centrifugeringen.","quick_fix":"Pausa, vänta tills trumman stannat och luckan öppnas, stäng av och dra ur kontakten och fördela tvätten jämnt (cirka 5 minuter).","intro_html":"<p>Bosch anger att E32/F32 betyder obalanserad last. Maskinen kan göra flera försök att fördela tvätten och därefter minska eller stoppa centrifugeringen för att skydda apparaten.</p><p>Det beror oftast på ett ensamt tungt plagg, hoptrasslad tvätt eller olämplig lastblandning. Det är normalt ingen reservdelsdiagnos.</p>","causes_json":[{"cause":"Tvätten har samlats på ena sidan","detail":"Lakan, handdukar och andra absorberande plagg kan klumpa ihop sig under programmet."},{"cause":"Ett ensamt tungt plagg","detail":"Ett vått tungt plagg kan sakna motvikt och blir svårt för trumman att balansera."},{"cause":"För liten eller olämpligt blandad last","detail":"Bosch rekommenderar att stora och små plagg tvättas tillsammans för bättre fördelning."},{"cause":"Maskinen står inte stabilt","detail":"Om koden återkommer med flera balanserade laster bör installation och nivellering kontrolleras enligt manualen."}],"steps_json":[{"step":1,"action":"Pausa och vänta","detail":"Pausa programmet och vänta tills trumman står helt stilla. Tvinga inte upp en låst lucka."},{"step":2,"action":"Töm enligt manualen vid behov","detail":"Om vatten håller luckan låst använder du modellens dokumenterade tömningsfunktion. Följ exakt manual."},{"step":3,"action":"Stäng av och koppla ur","detail":"När luckan kan öppnas stänger du av och drar ur kontakten innan tvätten justeras."},{"step":4,"action":"Fördela lasten","detail":"Red ut tvätten och blanda stora och små plagg. Lägg inte tillbaka ett ensamt tungt plagg utan lämplig motvikt."},{"step":5,"action":"Kontrollera programgränsen","detail":"Kontrollera lasttyp och viktgräns i manualen för valt program."},{"step":6,"action":"Starta om och observera","detail":"Kör ett lämpligt program och stoppa maskinen om den vandrar eller slår kraftigt."},{"step":7,"action":"Boka service vid återkomst","detail":"Om E32/F32 återkommer med flera korrekt balanserade laster bokar du service och öppnar inga paneler."}],"when_to_call_technician_html":"<p>Boka service om E32/F32 återkommer med flera olika, korrekt fyllda och jämnt fördelade laster efter att maskinen kontrollerats enligt installationsmanualen.</p><p>Sluta använda maskinen vid kraftiga slag, vandring över golvet, skrapande ljud eller synlig skada. Ta inte bort paneler eller inspektera upphängning och drivsystem själv.</p>","prevention_html":"<p>Blanda stora och små plagg, red ut lakan och påslakan och följ viktgränsen för valt program.</p><p>Håll maskinen plant och stabilt enligt installationsmanualen och undvik att tvätta ett ensamt absorberande tungt plagg.</p>","parts_json":[]})
  return v
 v=build_en('E32','an unbalanced load has been detected','Pause the cycle, wait for the drum to stop, and redistribute the laundry evenly')
 v.update({"title_tag":"Bosch Washing Machine E32: Balance the Laundry","meta_description":"Bosch washer showing E32 or F32? Learn how to redistribute the laundry safely, check the load and know when repeated imbalance needs service.","description":"Bosch identifies E32/F32 as an unbalanced load that may reduce or stop the spin cycle.","quick_fix":"Pause, wait for the drum and door to release, then switch off and unplug before redistributing the laundry evenly (about 5 minutes).","intro_html":"<p>Bosch identifies E32/F32 as an unbalanced load. The washer may make several redistribution attempts, then reduce or stop the spin to protect the appliance.</p><p>The usual reasons are one heavy item, tangled laundry or an unsuitable mix of items. The code is not normally a replacement-parts diagnosis.</p>","causes_json":[{"cause":"Laundry gathered on one side","detail":"Sheets, towels and other absorbent items can bunch together during the programme."},{"cause":"A single heavy item","detail":"One wet heavy item may have no counterweight and can be difficult for the drum to balance."},{"cause":"A small or unsuitable load mix","detail":"Bosch recommends washing large and small items together to improve distribution."},{"cause":"The washer is not stable","detail":"If the code returns with several balanced loads, check installation and levelling according to the manual."}],"steps_json":[{"step":1,"action":"Pause and wait","detail":"Pause the programme and wait until the drum stops completely. Do not force a locked door."},{"step":2,"action":"Drain according to the manual if needed","detail":"If retained water keeps the door locked, use the documented drain function for the model."},{"step":3,"action":"Switch off and unplug","detail":"Once the door can open, switch off and unplug before adjusting the load."},{"step":4,"action":"Redistribute the load","detail":"Untangle the laundry and mix large and small items. Do not return one heavy item without suitable balancing items."},{"step":5,"action":"Check the programme limit","detail":"Check the load type and weight limit for the selected programme in the manual."},{"step":6,"action":"Restart and observe","detail":"Run a suitable programme and stop the washer if it walks or strikes the cabinet heavily."},{"step":7,"action":"Request service if it returns","detail":"If E32/F32 returns with several correctly balanced loads, arrange service and do not open any panels."}],"when_to_call_technician_html":"<p>Arrange service if E32/F32 returns with several different, correctly sized and evenly distributed loads after the washer has been checked according to its installation manual.</p><p>Stop using it for heavy impacts, walking, scraping noise or visible damage. Do not remove panels or inspect suspension and drive parts yourself.</p>","prevention_html":"<p>Mix large and small items, untangle sheets and covers and follow the selected programme's load limit.</p><p>Keep the washer level and stable according to its installation manual, and avoid washing one absorbent heavy item alone.</p>","parts_json":[]})
 return v

